<?php
require dirname(__DIR__).'/config/bootstrap.php';require_role('super_admin');
$fields=['nama_laboratorium','nama_instansi','nomor_registrasi','nomor_akreditasi','berlaku_akreditasi','alamat','desa','kecamatan','kabupaten','provinsi','kode_pos','telepon','whatsapp','email','website','kepala_laboratorium','nip_kepala','footer_laporan','catatan_laporan'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=[];foreach($fields as $f)$data[$f]=trim($_POST[$f]??'');$id=(int)($_POST['id']??0);if($id){$set=implode(',',array_map(fn($f)=>"$f=?",$fields));$pdo->prepare("UPDATE laboratorium SET $set,updated_at=NOW() WHERE id=?")->execute([...array_values($data),$id]);}else{$pdo->prepare('INSERT INTO laboratorium('.implode(',',$fields).') VALUES('.implode(',',array_fill(0,count($fields),'?')).')')->execute(array_values($data));}audit($pdo,'Memperbarui identitas laboratorium','laboratorium',$id?:1,null,$data);flash('success','Identitas laboratorium disimpan.');redirect('laboratorium/index.php');}
$lab=$pdo->query('SELECT * FROM laboratorium ORDER BY id LIMIT 1')->fetch()?:[];$pageTitle='Identitas Laboratorium';require APP_ROOT.'/includes/header.php';?>
<form method="post"><input type="hidden" name="id" value="<?=$lab['id']??0?>"><?=csrf_field()?><div class="card"><div class="card-header bg-white py-3"><b>Identitas Laboratorium</b></div><div class="card-body"><div class="row g-3"><?php foreach($fields as $f):$label=ucwords(str_replace('_',' ',$f));?><div class="<?=in_array($f,['alamat','footer_laporan','catatan_laporan'])?'col-12':'col-md-6'?>"><label class="form-label <?=$f==='nama_laboratorium'?'required':''?>"><?=e($label)?></label><?php if(in_array($f,['alamat','footer_laporan','catatan_laporan'])):?><textarea class="form-control" name="<?=$f?>"><?=e($lab[$f]??'')?></textarea><?php else:?><input class="form-control" <?=$f==='berlaku_akreditasi'?'type="date"':''?> name="<?=$f?>" value="<?=e($lab[$f]??'')?>" <?=$f==='nama_laboratorium'?'required':''?>><?php endif;?></div><?php endforeach;?></div></div><div class="card-footer bg-white text-end"><button class="btn btn-primary">Simpan perubahan</button></div></div></form><?php require APP_ROOT.'/includes/footer.php';

